/* ============ Flex 布局 ============ */

/* 水平垂直居中 */
.center {
  display: flex;
  justify-content: center;
  align-items: center;
}

/* 等分三栏（忽略内容尺寸） */
.three-cols {
  display: flex;
  gap: 16px;
}
.three-cols > * {
  flex: 1; /* flex: 1 1 0% */
}

/* 固定侧边栏 + 自适应主内容 */
.sidebar-layout {
  display: flex;
}
.sidebar-layout .sidebar {
  flex: 0 0 240px; /* 不放大、不缩小、固定 240px */
}
.sidebar-layout .main {
  flex: 1 1 0%; /* 占满剩余空间 */
  min-width: 0; /* 关键：防止内容撑破 */
}

/* sticky footer（内容不足时 footer 贴底） */
.sticky-footer {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}
.sticky-footer .content {
  flex: 1; /* 撑开中间区域，footer 被推到底部 */
}

/* ============ Grid 布局 ============ */

/* 圣杯布局（命名区域） */
.holy-grail {
  display: grid;
  grid-template:
    "header header header" auto
    "nav    main   aside" 1fr
    "footer footer footer" auto
    / 200px 1fr 200px;
  min-height: 100vh;
}
.holy-grail .header { grid-area: header; }
.holy-grail .nav    { grid-area: nav; }
.holy-grail .main   { grid-area: main; }
.holy-grail .aside  { grid-area: aside; }
.holy-grail .footer { grid-area: footer; }

/* 响应式卡片网格 */
.card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 24px;
}

/* Grid 骨架 + Flex 局部排列（组合使用） */
.dashboard {
  display: grid;
  grid-template-columns: 240px 1fr;
  grid-template-rows: 60px 1fr;
  grid-template-areas:
    "sidebar header"
    "sidebar main";
  height: 100vh;
}
.dashboard .header {
  grid-area: header;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
